#!/bin/sh
scan_security() { SECURITY_UID=$(id -u 2>/dev/null || printf unknown); [ "$SECURITY_UID" = 0 ] && SECURITY_ROOT=true || SECURITY_ROOT=false; SECURITY_CAPS=$(read_one /proc/self/status | sed -n 's/^CapEff:[[:space:]]*//p'); SECURITY_SELINUX=unknown; [ -e "$(path /sys/fs/selinux/enforce)" ] && SECURITY_SELINUX=enabled; SECURITY_APPARMOR=unknown; [ -r "$(path /sys/module/apparmor/parameters/enabled)" ] && SECURITY_APPARMOR=$(read_one /sys/module/apparmor/parameters/enabled); SECURITY_SECCOMP=unknown; SECURITY_TPM=false; [ -e "$(path /dev/tpm0)" ] || [ -e "$(path /dev/tpmrm0)" ] && SECURITY_TPM=true; SECURITY_SECUREBOOT=unknown; [ -r "$(path /sys/firmware/efi/efivars/SecureBoot-8be4df61-93ca-11d2-aa0d-00e098032b8c)" ] && SECURITY_SECUREBOOT=present; SECURITY_ROOTFS=${STORAGE_ROOT_MODE:-unknown}; }
security_json() { printf '{"effective_uid":'; json_quote "$SECURITY_UID"; printf ',"is_root":%s,"effective_capabilities_hex":' "$SECURITY_ROOT"; json_quote "$SECURITY_CAPS"; printf ',"selinux":'; json_quote "$SECURITY_SELINUX"; printf ',"apparmor":'; json_quote "$SECURITY_APPARMOR"; printf ',"seccomp":'; json_quote "$SECURITY_SECCOMP"; printf ',"tpm_present":%s,"secure_boot":' "$SECURITY_TPM"; json_quote "$SECURITY_SECUREBOOT"; printf ',"root_filesystem_mode":'; json_quote "$SECURITY_ROOTFS"; printf '}'; }
